import { test, expect } from '@playwright/test';

test.describe('External Links Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com');
  });

  test('should open external link in a new tab', async ({ page }) => {
    const externalLink = page.getByRole('link', { name: 'External Site' });
    await externalLink.click();

    const [newPage] = await Promise.all([
      page.waitForEvent('popup'),
      externalLink.click(),
    ]);

    expect(newPage.url()).toBe('https://externalsite.com');
  });

  test('should not navigate away from the original page', async ({ page }) => {
    const originalPageUrl = page.url();
    const externalLink = page.getByRole('link', { name: 'External Site' });

    await externalLink.click();

    expect(page.url()).toBe(originalPageUrl);
  });
});
